from taf.ul.mobile.ui.android.adb_proxy import (AdbProxy, Android10AdbProxy, Android11AdbProxy,
                                                Android12AdbProxy, Android13AdbProxy, Android14AdbProxy)
from taf.ul.mobile.ui.android.exceptions import AndroidVersionNotSupported


class SupportedAdbProxies(object):

    _adb_proxies = {'android': AdbProxy,
                    'android10': Android10AdbProxy,
                    'android11': Android11AdbProxy,
                    'android12': Android12AdbProxy,
                    'android13': Android13AdbProxy,
                    'android14': Android14AdbProxy,
                    }

    _ANDROID = _adb_proxies['android']
    _ANDROID10 = _adb_proxies['android10']
    _ANDROID11 = _adb_proxies['android11']
    _ANDROID12 = _adb_proxies['android12']
    _ANDROID13 = _adb_proxies['android13']
    _ANDROID14 = _adb_proxies['android14']

    def __getitem__(self, name):
        try:
            return getattr(self, '_ANDROID{}'.format(name.upper()))
        except AttributeError:
            raise AndroidVersionNotSupported('Android version {} is not supported'.format(name))
